const api = async (path, options = {}) => {
  const response = await fetch(`/api/v1${path}`, { credentials: 'include', headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.error?.message || `Request failed (${response.status})`);
  return data;
};
const apiV3 = async (path, options = {}) => {
  const response = await fetch(`/api/v3${path}`, { credentials: 'include', headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.error?.message || `Request failed (${response.status})`);
  return data;
};
function Login({ onSuccess }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async event => { event.preventDefault(); setBusy(true); setError(''); try { await api('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); onSuccess(); } catch (e) { setError(e.message); } finally { setBusy(false); } };
  return <main className="login"><section><span className="eyebrow">FLESHLAB / V3 PREVIEW</span><h1>Operations<br/><i>in focus.</i></h1><p>Self-hosted V3 foundation. Use your existing FLESHLAB account.</p><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} required /></label>{error && <p className="error">{error}</p>}<button disabled={busy}>{busy ? 'Signing in…' : 'Enter V3'}</button></form></section><aside><p>FLESHLAB V3</p><strong>Built beside V2.<br/>Not over it.</strong></aside></main>;
}
const nav = ['Overview', 'Catalogue', 'Creators', 'Contracts', 'Production', 'Growth', 'Commerce', 'System'];
