function CreatorWorkspace({user,onLogout}) {
  const [data,setData]=useState(null),[contracts,setContracts]=useState([]),[error,setError]=useState('');
  useEffect(()=>{Promise.all([apiV3('/creator/me'),apiV3('/creator/contracts')]).then(([creator,pack])=>{setData(creator);setContracts(pack.records||[]);}).catch(e=>setError(e.message));},[]);
  return <main className="creator-app"><header><a className="brand" href="/v3/">FLESH<span>LAB</span><small>CREATOR WORKSPACE</small></a><button onClick={onLogout}>Sign out</button></header>{error?<section className="creator-hero"><span className="eyebrow">CREATOR ACCESS</span><h1>Your workspace is not linked yet.</h1><p>{error}</p><p>A FLESHLAB administrator must link your approved creator profile before private V3 records can be shown.</p></section>:!data?<p>Loading your private workspace…</p>:<><section className="creator-hero"><span className="eyebrow">YOUR NEXT STEPS</span><h1>{data.creator.full_name}</h1><p>{data.onboarding.filter(item=>item.state!=='complete').length} onboarding actions still need attention.</p></section><div className="creator-mobile-grid"><section><span className="eyebrow">ONBOARDING</span>{data.onboarding.map(item=><article key={item.id}><b>{item.requirement_key.replaceAll('_',' ')}</b><span>{item.state}</span><p>{item.note||'No additional note.'}</p></article>)}</section><section><span className="eyebrow">CONTRACTS</span>{contracts.length?contracts.map(item=><article key={item.id}><b>{item.title||item.contract_number}</b><span>{item.status} · {item.version||'legacy'}</span><a href={`/api/v3/creator/contracts/${item.id}/pdf`}>View / download PDF</a></article>):<Empty title="No contract assigned" body="Contract status appears here when FLESHLAB assigns a reviewed contract."/>}</section><section><span className="eyebrow">CONTENT</span>{data.videos.length?data.videos.map(video=><article key={video.legacy_id}><b>{video.title}</b><span>{video.v3_lifecycle}</span></article>):<Empty title="No linked content" body="Your linked catalogue content will appear here."/>}</section><section><span className="eyebrow">DOCUMENTS</span>{data.documents.length?data.documents.map(doc=><article key={doc.id}><b>{doc.file_name}</b><span>{doc.review_state}</span></article>):<Empty title="No confirmed documents" body="Required private documents appear after a secure upload is confirmed."/>}</section></div></>}</main>;
}
function CatalogueLegacy({ section }) {
  const [kind, setKind] = useState('videos'); const [data, setData] = useState({ records: [] }); const [q, setQ] = useState('');
  const [selected, setSelected] = useState(null); const [detail, setDetail] = useState(null); const [collectionDetail, setCollectionDetail] = useState(null); const [error, setError] = useState(''); const [collections, setCollections] = useState([]); const [report, setReport] = useState(null); const [collectionTitle, setCollectionTitle] = useState('');
  const load = async () => { try { if (kind === 'collections') { setCollections((await apiV3('/admin/catalogue/collections')).records); return; } setData(await apiV3(`/admin/catalogue/${kind}?q=${encodeURIComponent(q)}&limit=24`)); } catch (e) { setError(e.message); } };
  useEffect(() => { if (section === 'Catalogue') load(); }, [section, kind]);
  if (section !== 'Catalogue') return null;
  const singular = kind === 'videos' ? 'video' : kind === 'brands' ? 'brand' : 'performer';
  const open = async row => { setSelected(row); setDetail(await apiV3(`/admin/catalogue/${singular}/${row.legacy_id}`)); };
  const openCollection = async row => { const videos = await apiV3(`/admin/catalogue/collections/${row.id}/videos`); setCollectionDetail({ ...row, videoIds: videos.records.map(video => video.legacy_id).join(', ') }); };
  const change = (field, value) => setDetail({ ...detail, record: { ...detail.record, [field]: value } });
  const save = async () => { const record = detail.record; const patch = { title: record.title, name: record.name, display_name: record.display_name, slug: record.slug, description: record.description, bio: record.bio, v3_lifecycle: record.v3_lifecycle }; await apiV3(`/admin/catalogue/${singular}/${record.legacy_id}`, { method: 'PATCH', body: JSON.stringify(patch) }); await open(record); await load(); };
  const rows = kind === 'collections' ? collections : data.records;
  const createCollection = async event => { event.preventDefault(); if (!collectionTitle.trim()) return; try { await apiV3('/admin/catalogue/collections', { method: 'POST', body: JSON.stringify({ title: collectionTitle }) }); setCollectionTitle(''); await load(); } catch (e) { setError(e.message); } };
  const saveCollection = async () => { try { await apiV3(`/admin/catalogue/collections/${collectionDetail.id}`, { method: 'PATCH', body: JSON.stringify(collectionDetail) }); const video_ids = collectionDetail.videoIds.split(',').map(value => value.trim()).filter(Boolean); await apiV3(`/admin/catalogue/collections/${collectionDetail.id}/videos`, { method: 'PUT', body: JSON.stringify({ video_ids }) }); await load(); setCollectionDetail(null); } catch (e) { setError(e.message); } };
  const showReport = async () => { try { setReport(await apiV3('/admin/catalogue/migration-report')); } catch (e) { setError(e.message); } };
  return <section className="catalogue"><div className="catalogue-head"><div><span className="eyebrow">CATALOGUE DOMAIN</span><h2>Live library.</h2></div><div><p>{data.total ?? collections.length} real records</p><button className="report-button" onClick={showReport}>Migration report</button></div></div><div className="tabs">{['videos','performers','brands','collections'].map(tab => <button className={kind === tab ? 'active' : ''} key={tab} onClick={() => { setKind(tab); setSelected(null); setDetail(null); }}>{tab}</button>)}</div>{kind !== 'collections' && <input className="search" value={q} onChange={e => setQ(e.target.value)} onKeyDown={e => e.key === 'Enter' && load()} placeholder={`Search ${kind}`}/>} {kind === 'collections' && <form className="collection-form" onSubmit={createCollection}><input value={collectionTitle} onChange={e => setCollectionTitle(e.target.value)} placeholder="New collection title"/><button>Create collection</button></form>} {error && <p className="error">{error}</p>}<div className="catalogue-grid">{rows.map(row => <button className="record" key={row.id || row.legacy_id} onClick={() => kind === 'collections' ? openCollection(row) : open(row)}>{row.legacy_thumbnail_url ? <img src={row.legacy_thumbnail_url} alt=""/> : <div className="poster"/>}<span>{row.v3_lifecycle || row.visibility || row.status}</span><h3>{row.title || row.display_name || row.name}</h3><small>{row.performer_names?.join(' · ') || (row.video_count != null ? `${row.video_count} videos` : row.slug)}</small></button>)}</div>{report && <aside className="detail"><button onClick={() => setReport(null)}>Close</button><span className="eyebrow">MIGRATION REPORT</span><h2>Canonical import</h2><p>Accepted relationships: {report.runs?.[0]?.summary?.credits ?? '—'}</p><p>Rejected relationships: {report.runs?.[0]?.summary?.skipped_credits ?? '—'}</p><pre>{JSON.stringify(report, null, 2)}</pre></aside>}{collectionDetail && <aside className="detail"><button onClick={() => setCollectionDetail(null)}>Close</button><span className="eyebrow">COLLECTION DETAIL</span><h2>{collectionDetail.title}</h2><label>Title<input value={collectionDetail.title || ''} onChange={e => setCollectionDetail({ ...collectionDetail, title: e.target.value })}/></label><label>Slug<input value={collectionDetail.slug || ''} onChange={e => setCollectionDetail({ ...collectionDetail, slug: e.target.value })}/></label><label>Description<textarea value={collectionDetail.description || ''} onChange={e => setCollectionDetail({ ...collectionDetail, description: e.target.value })}/></label><label>Video IDs, comma separated<textarea value={collectionDetail.videoIds} onChange={e => setCollectionDetail({ ...collectionDetail, videoIds: e.target.value })}/></label><button className="save" onClick={saveCollection}>Save collection</button></aside>}{selected && detail && <aside className="detail"><button onClick={() => setSelected(null)}>Close</button><span className="eyebrow">{kind.slice(0,-1)} DETAIL</span><h2>{detail.record.title || detail.record.display_name || detail.record.name}</h2><label>Title / name<input value={detail.record.title || detail.record.display_name || detail.record.name || ''} onChange={e => change(kind === 'videos' ? 'title' : kind === 'performers' ? 'display_name' : 'name', e.target.value)}/></label><label>Slug<input value={detail.record.slug || ''} onChange={e => change('slug', e.target.value)}/></label><label>Description<textarea value={detail.record.description || detail.record.bio || ''} onChange={e => change(kind === 'performers' ? 'bio' : 'description', e.target.value)}/></label>{kind === 'videos' && <><label>Lifecycle<select value={detail.record.v3_lifecycle || 'draft'} onChange={e => change('v3_lifecycle', e.target.value)}>{['draft','metadata_ready','media_ready','qa_review','certification_review','publishable','published','archived'].map(x => <option key={x}>{x}</option>)}</select></label><p className="blockers">Publish: {detail.publish?.publishable ? 'ready' : detail.publish?.blockers.join(', ')}</p><p>Performers: {detail.record.performers?.map(x => x.name).join(', ') || 'none'}</p></>}<button className="save" onClick={save}>Save metadata</button><pre>{JSON.stringify(detail.audit || [], null, 2)}</pre></aside>}</section>;
}
function Catalogue({ section }) {
  const [kind,setKind]=useState('videos'); const [data,setData]=useState({records:[]}); const [q,setQ]=useState(''); const [page,setPage]=useState(1); const [filters,setFilters]=useState({lifecycle:'',status:'',missing_media:'',brand:'',performer:'',collection:''}); const [detail,setDetail]=useState(null); const [collections,setCollections]=useState([]); const [error,setError]=useState('');
  const load=async()=>{try{if(kind==='collections'){setCollections((await apiV3('/admin/catalogue/collections')).records||[]);return;}const params=new URLSearchParams({limit:'24',page:String(page),q,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))});setData(await apiV3(`/admin/catalogue/${kind}?${params}`));}catch(e){setError(e.message);}};
  useEffect(()=>{if(section==='Catalogue')load();},[section,kind,filters]); if(section!=='Catalogue')return null;
  const singular=kind==='videos'?'video':kind==='brands'?'brand':'performer'; const open=async row=>{try{setDetail(await apiV3(`/admin/catalogue/${singular}/${row.legacy_id}`));}catch(e){setError(e.message);}};
  const change=(field,value)=>setDetail({...detail,record:{...detail.record,[field]:value}});
  const save=async()=>{try{const r=detail.record;await apiV3(`/admin/catalogue/${singular}/${r.legacy_id}`,{method:'PATCH',body:JSON.stringify({...r,seo_title:r.seo_title,seo_description:r.seo_description,internal_publishing_notes:r.internal_publishing_notes})});await open(r);await load();}catch(e){setError(e.message);}};
  const transition=async action=>{try{await apiV3(`/admin/catalogue/video/${detail.record.legacy_id}/${action}`,{method:'POST',body:'{}'});await open(detail.record);await load();}catch(e){setError(e.message);}};
  const assignMedia=async()=>{try{await apiV3(`/admin/catalogue/video/${detail.record.legacy_id}/media`,{method:'PUT',body:JSON.stringify({asset_id:detail.mediaAssetId,asset_type:detail.mediaAssetType||'thumbnail'})});await open(detail.record);}catch(e){setError(e.message);}};
  const rows=kind==='collections'?collections:data.records||[];
  return <section className="catalogue"><div className="catalogue-head"><div><span className="eyebrow">CATALOGUE OPERATIONS</span><h2>Live library.</h2><p>Server-validated metadata, media and publishing controls.</p></div><div><p>{kind==='collections'?collections.length:data.total||0} records</p></div></div><div className="tabs">{['videos','performers','brands','collections'].map(tab=><button className={kind===tab?'active':''} key={tab} onClick={()=>{setKind(tab);setPage(1);setDetail(null);}}>{tab}</button>)}</div>{kind!=='collections'&&<div className="catalogue-filters"><input className="search" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){setPage(1);load();}}} placeholder={`Search ${kind}`}/>{kind==='videos'&&<><select value={filters.lifecycle} onChange={e=>setFilters({...filters,lifecycle:e.target.value})}><option value="">All lifecycle</option>{['draft','metadata_ready','media_ready','qa_review','certification_review','publishable','published','archived'].map(v=><option key={v}>{v}</option>)}</select><select value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">All status</option>{['draft','published','unlisted','archived'].map(v=><option key={v}>{v}</option>)}</select><input placeholder="Brand ID" value={filters.brand} onChange={e=>setFilters({...filters,brand:e.target.value})}/><input placeholder="Performer ID" value={filters.performer} onChange={e=>setFilters({...filters,performer:e.target.value})}/><input placeholder="Collection ID" value={filters.collection} onChange={e=>setFilters({...filters,collection:e.target.value})}/><label><input type="checkbox" checked={filters.missing_media==='true'} onChange={e=>setFilters({...filters,missing_media:e.target.checked?'true':''})}/> missing media</label></>}</div>}{error&&<p className="error">{error}</p>}<div className="catalogue-grid">{rows.map(row=><button className="record" key={row.id||row.legacy_id} onClick={()=>kind==='collections'?null:open(row)}>{row.legacy_thumbnail_url?<img src={row.legacy_thumbnail_url} alt=""/>:<div className="poster"/>}<span>{row.v3_lifecycle||row.visibility||row.status}</span><h3>{row.title||row.display_name||row.name}</h3><small>{row.performer_names?.join(' · ')|| (row.video_count!=null?`${row.video_count} videos`:row.slug)}</small></button>)}</div>{kind!=='collections'&&<div className="pagination"><button disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {data.pages||1}</span><button disabled={page>=(data.pages||1)} onClick={()=>setPage(page+1)}>Next</button></div>}{detail&&<aside className="detail"><button onClick={()=>setDetail(null)}>Close</button><span className="eyebrow">{singular.toUpperCase()} DETAIL</span><h2>{detail.record.title||detail.record.display_name||detail.record.name}</h2><label>Title / name<input value={detail.record.title||detail.record.display_name||detail.record.name||''} onChange={e=>change(kind==='videos'?'title':kind==='performers'?'display_name':'name',e.target.value)}/></label><label>Slug<input value={detail.record.slug||''} onChange={e=>change('slug',e.target.value)}/></label><label>Description<textarea value={detail.record.description||detail.record.bio||''} onChange={e=>change(kind==='performers'?'bio':'description',e.target.value)}/></label>{kind==='videos'&&<><label>Summary<textarea value={detail.record.short_summary||''} onChange={e=>change('short_summary',e.target.value)}/></label><label>Lifecycle<select value={detail.record.v3_lifecycle||'draft'} onChange={e=>change('v3_lifecycle',e.target.value)}>{['draft','metadata_ready','media_ready','qa_review','certification_review','publishable','published','archived'].map(v=><option key={v}>{v}</option>)}</select></label><label>SEO title<input value={detail.record.seo_title||''} onChange={e=>change('seo_title',e.target.value)}/></label><label>SEO description<textarea value={detail.record.seo_description||''} onChange={e=>change('seo_description',e.target.value)}/></label><label>Internal publishing notes<textarea value={detail.record.internal_publishing_notes||''} onChange={e=>change('internal_publishing_notes',e.target.value)}/></label><div className="readiness-panel"><b>{detail.publish?.publishable?'READY TO PUBLISH':'PUBLISH BLOCKED'}</b><ul>{(detail.publish?.blockers||[]).map(b=><li key={b}>{b}</li>)}</ul>{(detail.publish?.warnings||[]).map(w=><small key={w}>Warning: {w}</small>)}</div><p>Performers: {detail.record.performers?.map(x=>x.name).join(', ')||'none'}</p><p>Media: {(detail.media||[]).map(x=>`${x.asset_type}:${x.processing_state}/${x.visibility}${x.is_primary?' (primary)':''}`).join(' · ')||'none assigned'}</p><label>Assign ready public asset ID<input value={detail.mediaAssetId||''} onChange={e=>setDetail({...detail,mediaAssetId:e.target.value})}/></label><select value={detail.mediaAssetType||'thumbnail'} onChange={e=>setDetail({...detail,mediaAssetType:e.target.value})}><option>thumbnail</option><option>poster</option><option>trailer</option></select><button onClick={assignMedia}>Assign media</button><div className="button-row"><button className="save" onClick={()=>transition('publish')} disabled={!detail.publish?.publishable}>Publish</button><button onClick={()=>transition('unpublish')}>Unpublish</button><button onClick={()=>transition('archive')}>Archive</button></div></>}<button className="save" onClick={save}>Save metadata</button><pre>{JSON.stringify(detail.audit||[],null,2)}</pre></aside>}</section>;
}

function V3Entry() {
  const pathname = window.location.pathname;
  const adminRequested = new URLSearchParams(window.location.search).get('admin') === '1';
  const publicPath = pathname !== '/v3/' && pathname !== '/v3';
  const [mode, setMode] = useState(publicPath || adminRequested ? (adminRequested ? 'admin' : 'public') : 'checking');
  useEffect(() => {
    if (publicPath || adminRequested) return;
    fetch('/api/v1/auth/me', { credentials: 'include' }).then((response) => setMode(response.ok ? 'admin' : 'public')).catch(() => setMode('public'));
  }, [publicPath, adminRequested]);
  if (mode === 'checking') return <main className="public-empty" style={{ minHeight: '100vh' }}>Loading catalogue…</main>;
  return mode === 'admin' ? <App /> : <PublicApp />;
}
createRoot(document.getElementById('root')).render(<V3Entry/>);
